export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

export function raiseNegativeShiftCount() {
  throw new ValueError('negative shift count');
}

import { raiseNegativeShiftCount } from '../runtime/python-errors.mjs';

function toBigInt(value) {
  return BigInt(value);
}

function leftShift(value, count) {
  if (count < 0) {
    raiseNegativeShiftCount();
  }

  return value << toBigInt(count);
}

function rightShift(value, count) {
  if (count < 0) {
    raiseNegativeShiftCount();
  }

  return value >> toBigInt(count);
}

function bitMask(count) {
  return leftShift(1n, count) - 1n;
}

function toOutputNumber(value) {
  return Number(value);
}

export function convertBits(data, fromBits, toBits, pad = true) {
  if (data === null) {
    throw new TypeError("'NoneType' object is not iterable");
  }

  let accumulator = 0n;
  let bits = 0;
  const result = [];
  const maxValue = bitMask(toBits);
  const maxAccumulator = bitMask(fromBits + toBits - 1);

  for (const item of data) {
    const value = toBigInt(item);

    if (value < 0n || rightShift(value, fromBits) !== 0n) {
      return null;
    }

    accumulator = (leftShift(accumulator, fromBits) | value) & maxAccumulator;
    bits += fromBits;

    while (bits >= toBits) {
      bits -= toBits;
      result.push(toOutputNumber(rightShift(accumulator, bits) & maxValue));
    }
  }

  if (pad) {
    if (bits !== 0) {
      result.push(toOutputNumber(leftShift(accumulator, toBits - bits) & maxValue));
    }
  } else if (bits >= fromBits || (leftShift(accumulator, toBits - bits) & maxValue) !== 0n) {
    return null;
  }

  return result;
}

import { ValueError } from '../runtime/python-errors.mjs';

const INTEGER_PATTERN = /^[+-]?\d+$/;

function normalizeIntegerText(text) {
  return String(text).trim();
}

export function tryParseArgumentInt(text) {
  const normalized = normalizeIntegerText(text);

  if (!INTEGER_PATTERN.test(normalized)) {
    return null;
  }

  return Number.parseInt(normalized, 10);
}

export function parsePythonIntLiteral(text) {
  const normalized = normalizeIntegerText(text);

  if (!INTEGER_PATTERN.test(normalized)) {
    throw new ValueError(`invalid literal for int() with base 10: '${text}'`);
  }

  return Number.parseInt(normalized, 10);
}

export function parseCommaSeparatedIntegers(text) {
  return String(text)
    .split(',')
    .map((item) => parsePythonIntLiteral(item));
}

export function formatPythonValue(value) {
  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => String(item)).join(', ')}]`;
  }

  return String(value);
}

import { tryParseArgumentInt } from '../number/python-int.mjs';

const OPTION_DEFINITIONS = [
  { key: 'a', flag: '--a', metavar: 'A', type: 'string' },
  { key: 'b', flag: '--b', metavar: 'B', type: 'int' },
  { key: 'c', flag: '--c', metavar: 'C', type: 'int' },
  { key: 'd', flag: '--d', metavar: 'D', type: 'int' },
];

const OPTION_MAP = new Map(OPTION_DEFINITIONS.map((definition) => [definition.flag, definition]));
const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;

function renderUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D`;
}

function renderHelp(programName) {
  return `${renderUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n  --d D\n`;
}

function renderError(programName, message) {
  return `${renderUsage(programName)}\n${programName}: error: ${message}\n`;
}

function isNegativeNumberLike(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function consumeKnownOptionValue(argv, index, definition, programName) {
  const nextToken = argv[index + 1];

  if (nextToken === undefined) {
    return {
      nextIndex: index,
      result: {
        kind: 'error',
        code: 2,
        text: renderError(programName, `argument ${definition.flag}: expected one argument`),
      },
    };
  }

  if (nextToken.startsWith('-') && !isNegativeNumberLike(nextToken)) {
    return {
      nextIndex: index,
      result: {
        kind: 'error',
        code: 2,
        text: renderError(programName, `argument ${definition.flag}: expected one argument`),
      },
    };
  }

  return {
    nextIndex: index + 1,
    result: {
      kind: 'value',
      rawValue: nextToken,
    },
  };
}

function parseOptionValue(rawValue, definition, programName) {
  if (definition.type === 'int') {
    const parsedValue = tryParseArgumentInt(rawValue);

    if (parsedValue === null) {
      return {
        kind: 'error',
        code: 2,
        text: renderError(programName, `argument ${definition.flag}: invalid int value: '${rawValue}'`),
      };
    }

    return {
      kind: 'value',
      value: parsedValue,
    };
  }

  return {
    kind: 'value',
    value: rawValue,
  };
}

function collectUnrecognizedToken(argv, index, unrecognized) {
  const token = argv[index];
  unrecognized.push(token);

  if (index + 1 < argv.length && !argv[index + 1].startsWith('-')) {
    unrecognized.push(argv[index + 1]);
    return index + 1;
  }

  return index;
}

export function parseArguments(argv, programName) {
  const values = {};
  const unrecognized = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        code: 0,
        text: renderHelp(programName),
      };
    }

    if (token === '--') {
      for (let remainder = index + 1; remainder < argv.length; remainder += 1) {
        unrecognized.push(argv[remainder]);
      }
      break;
    }

    if (token.startsWith('--')) {
      const separatorIndex = token.indexOf('=');
      const hasInlineValue = separatorIndex !== -1;
      const flag = hasInlineValue ? token.slice(0, separatorIndex) : token;
      const definition = OPTION_MAP.get(flag);

      if (!definition) {
        index = collectUnrecognizedToken(argv, index, unrecognized);
        continue;
      }

      const rawValueResult = hasInlineValue
        ? {
            nextIndex: index,
            result: {
              kind: 'value',
              rawValue: token.slice(separatorIndex + 1),
            },
          }
        : consumeKnownOptionValue(argv, index, definition, programName);

      index = rawValueResult.nextIndex;

      if (rawValueResult.result.kind === 'error') {
        return rawValueResult.result;
      }

      const parsedValue = parseOptionValue(rawValueResult.result.rawValue, definition, programName);

      if (parsedValue.kind === 'error') {
        return parsedValue;
      }

      values[definition.key] = parsedValue.value;
      continue;
    }

    if (token.startsWith('-')) {
      index = collectUnrecognizedToken(argv, index, unrecognized);
      continue;
    }

    unrecognized.push(token);
  }

  const missingRequired = OPTION_DEFINITIONS
    .filter((definition) => !(definition.key in values))
    .map((definition) => definition.flag);

  if (missingRequired.length > 0) {
    return {
      kind: 'error',
      code: 2,
      text: renderError(programName, `the following arguments are required: ${missingRequired.join(', ')}`),
    };
  }

  if (unrecognized.length > 0) {
    return {
      kind: 'error',
      code: 2,
      text: renderError(programName, `unrecognized arguments: ${unrecognized.join(' ')}`),
    };
  }

  return {
    kind: 'ok',
    values,
  };
}

import { basename } from 'node:path';

import { convertBits } from './lib/bech32/convert-bits.mjs';
import { parseArguments } from './lib/cli/parse-args.mjs';
import { formatPythonValue } from './lib/format/python-repr.mjs';
import { parseCommaSeparatedIntegers } from './lib/number/python-int.mjs';

function main() {
  const programName = basename(process.argv[1] ?? 'test14.mjs');
  const parseResult = parseArguments(process.argv.slice(2), programName);

  if (parseResult.kind === 'help') {
    process.stdout.write(parseResult.text);
    process.exit(0);
  }

  if (parseResult.kind === 'error') {
    process.stderr.write(parseResult.text);
    process.exit(parseResult.code);
  }

  const data = parseCommaSeparatedIntegers(parseResult.values.a);
  const step1 = convertBits(data, parseResult.values.b, parseResult.values.c);
  const step2 = convertBits(step1, parseResult.values.c, parseResult.values.d);

  process.stdout.write(`${formatPythonValue(step1)}\n${formatPythonValue(step2)}\n`);
}

main();
